(()=>{'use strict';const A=window.omniAddon,T=window.OBAddonTools;if(!A||!T||!A.top)return;const pending=new Map();function restore(a){const r=pending.get(a);if(r&&a.getAttribute('href')===r.clean)a.setAttribute('href',r.original);pending.delete(a)}function click(e){if(!A.active||!A.settings.get('enabled')||e.defaultPrevented)return;const a=e.target.closest?.('a[href]');if(!a||a.hasAttribute('download'))return;const original=a.getAttribute('href'),clean=T.cleanURL(original,location.href);if(clean===original)return;pending.set(a,{original,clean});a.setAttribute('href',clean);setTimeout(()=>restore(a),0)}function start(){document.addEventListener('click',click,true);document.addEventListener('auxclick',click,true)}function stop(){document.removeEventListener('click',click,true);document.removeEventListener('auxclick',click,true);for(const a of pending.keys())restore(a)}A.onDisable(stop);A.onEnable(start);start()})();